import { useEffect, useReducer } from "react";
import { generateAssignment, type Assignment, type AssignmentLength } from "@/game/assignments";
import { applyKey, createTyping, isFinished, type TypingState } from "@/game/typing";
import { useKeyInput } from "@/state/useKeyInput";
import { useNow } from "./useNow";

type Game = { assignment: Assignment; typing: TypingState; length: AssignmentLength };

type Action = { type: "key"; key: string; now: number } | { type: "next"; game: Game };

// Random text is generated by callers and passed in, so the reducer itself stays pure.
function newGame(tier: number, length: AssignmentLength): Game {
  const assignment = generateAssignment(tier, length, Math.random);
  return { assignment, typing: createTyping(assignment.text), length };
}

function reducer(game: Game, action: Action): Game {
  if (action.type === "next") return action.game;
  const typing = applyKey(game.typing, action.key, action.now);
  return typing === game.typing ? game : { ...game, typing };
}

/** Runs one assignment at a time from the shared keyboard input. Enter starts the next one when finished. */
export function useAssignment(tier: number) {
  const input = useKeyInput();
  const [game, dispatch] = useReducer(reducer, undefined, () => newGame(tier, "short"));
  const finished = isFinished(game.typing);
  const started = game.typing.startedAt !== null;
  const now = useNow(started && !finished);

  useEffect(
    () =>
      input.subscribe((key) => {
        if (!finished) dispatch({ type: "key", key, now: performance.now() });
        else if (key === "Enter") dispatch({ type: "next", game: newGame(tier, game.length) });
      }),
    [input, finished, tier, game.length],
  );

  return {
    ...game,
    now,
    finished,
    chooseLength: (length: AssignmentLength) => dispatch({ type: "next", game: newGame(tier, length) }),
  };
}
